export interface FieldMetadataMeta {
  version: string
  status: string
  source: string
}

export type RequirementLevel =
  | 'required'
  | 'recommended'
  | 'optional'
  | 'definition'
  | 'none'
  | 'mixed'
  | 'conditional_required'
  | 'conditional_recommended'

export interface FieldCondition {
  field: string
  op: string
  value: string | string[]
}

export interface FieldRequirement {
  raw: string
  level: RequirementLevel
  condition: FieldCondition | null
}

export interface FieldMetadata {
  key: string
  labelZh: string
  labelEn: string
  /** 字段输入形态（原样透传自 field-source.yaml） */
  input: string
  /** 单位（xlsx 占位符 "—" 归一为 null） */
  unit: string | null
  /** 原始可选项字符串（未拆结构化词表，P3 才做） */
  options: string | null
  requirement: FieldRequirement
  /** 是否属 R0 最小可复现集 */
  r0: boolean
  /** §5 过程步字段的参数组（stageGroups 的键）；其余字段为 null */
  group: string | null
  /** 条件不成立时隐藏，而非仅切换必填状态 */
  visibilityGated?: true
}

export interface StageType {
  name: string
  /** 该阶段显示哪些参数组（stageGroups 的键；common 恒显） */
  shows: string[]
  /** 该阶段额外强制必填的字段键 */
  requiredExtra?: string[]
}

